import React, { useState, useEffect } from 'react';

export default function LifecycleDemo() {
  const [count, setCount] = useState(0);

  // 1. MOUNTING & UNMOUNTING
  useEffect(() => {
    console.log("Phase 1: Component Mounted! (Like componentDidMount)");

    return () => {
      console.log("Phase 3: Component Unmounted! (Like componentWillUnmount)");
    };
  }, []); // Empty array means run once

  // 2. UPDATING
  useEffect(() => {
    if (count > 0) {
      console.log(`Phase 2: Component Updated! Count is now ${count}`);
    }
  }, [count]); // Runs whenever 'count' changes

  return (
    <div>
      <h2>Count: {count}</h2>
      <button onClick={() => setCount(c => c + 1)}>Trigger Update</button>
    </div>
  );
}
